const $=s=>document.querySelector(s);
const app=$('#app'),modal=$('#modal');
const state={user:null,csrf:'',ai:false,page:'overview',role:'student',attempt:null,index:0,questions:[],documents:[],students:[],catalog:[],analytics:null};
const paths={book:'M4 4h6a3 3 0 0 1 3 3v14a5 5 0 0 0-5-3H4V4Zm16 0h-4a3 3 0 0 0-3 3v14a5 5 0 0 1 5-3h2V4Z',home:'m3 10 9-7 9 7M5 9v11h5v-6h4v6h5V9',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.8M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',folder:'M3 7V4h6l2 3h10v13H3V7Z',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3ZM20 2v4M18 4h4',chart:'M4 20V10M10 20V4M16 20v-7M22 20H2',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',check:'m5 12 4 4L19 6',arrow:'M5 12h14m-5-5 5 5-5 5',plus:'M12 5v14M5 12h14',logout:'M9 4H4v16h5M10 12h11m-5-5 5 5-5 5',sun:'M12 3v2M12 19v2M3 12h2M19 12h2M5 5l1.5 1.5M17.5 17.5 1.5 1.5M5 19l1.5-1.5M17.5 6.5 1.5-1.5M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',shield:'m12 3 8 3v6c0 4-4 7-8 9-4-2-8-5-8-9V6l8-3Zm-4 9 3 3 5-6',menu:'M3 6h18M3 12h18M3 18h18',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0M12 11v2',file:'M14 3H5v18h14V8l-5-5Zm0 0v6h5M8 13h8M8 17h6',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',upload:'M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dlabel={easy:'Dễ',medium:'Trung bình',hard:'Khó'};
const slabel={draft:'Bản nháp',approved:'Đã duyệt',published:'Đã xuất bản',retired:'Ngừng sử dụng',extracted:'Đã trích xuất',analyzed:'Đã phân tích',confirmed:'Đã xác nhận'};
const date=v=>v?new Date(v).toLocaleString('vi-VN',{dateStyle:'short',timeStyle:'short'}):'—';
const badge=(text,cls='')=>`<span class="pill ${cls}">${e(text)}</span>`;
const empty=text=>`<div class="empty">${icon('book')}<p>${e(text)}</p></div>`;
const field=(label,name,value='',type='text',extra='')=>`<div class="field"><label for="f-${name}">${e(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}></div>`;
const area=(label,name,value='',extra='')=>`<div class="field"><label for="f-${name}">${e(label)}</label><textarea id="f-${name}" name="${name}" ${extra}>${e(value)}</textarea></div>`;
const select=(label,name,options,value='')=>`<div class="field"><label for="f-${name}">${e(label)}</label><select name="${name}" id="f-${name}">${options.map(([v,l])=>`<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(l)}</option>`).join('')}</select></div>`;
const buttons=label=>`<div class="form-actions"><button type="button" class="secondary" data-action="close">Hủy</button><button class="primary" type="submit">${e(label)}</button></div>`;
const title=(heading,sub,action='')=>`<div class="page-head"><div><h1>${e(heading)}</h1><p>${e(sub)}</p></div>${action}</div>`;
const btn=(label,action,id='',primary=false)=>`<button class="${primary?'primary':'secondary'}" data-action="${action}" data-id="${e(id)}">${e(label)}</button>`;
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',6000);}
function showModal(heading,content){modal.innerHTML=`<div class="dialog-head"><h2>${e(heading)}</h2><button data-action="close" aria-label="Đóng">×</button></div>${content}`;if(!modal.open)modal.showModal();}
async function api(path,data){const response=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:data===undefined?undefined:JSON.stringify(data)});const result=await response.json();if(!response.ok){if(response.status===401&&path!=='login'){state.user=null;renderLogin();}throw new Error(result.error||'Không thể xử lý yêu cầu.');}return result;}
function theme(){document.documentElement.dataset.theme=localStorage.getItem('btvn-theme')||'light';}
theme();

function renderLogin(){
 app.innerHTML=`<main class="login"><section class="login-story"><div class="brand"><span class="brand-icon">${icon('book')}</span>BTVN<span class="pill gold">AI</span></div><h1>Hiểu từng bước.<br> <em>Tiến bộ mỗi ngày.</em></h1><p>Một không gian để thầy cô đồng hành,<br> để mỗi học sinh tự tin hơn trên hành trình học tập.</p><div class="login-illustration">${art()}<div class="login-tag">${icon('check')} Mỗi bước nhỏ, một tiến bộ lớn</div></div><footer>HỌC CÓ HƯỚNG DẪN · TIẾN BỘ CÓ DẤU ẤN</footer></section><section class="login-form-wrap"><div class="login-form"><span class="eyebrow">CHÀO MỪNG ĐẾN VỚI BTVN</span><h2>Không gian của bạn</h2><p>Đăng nhập để tiếp tục hành trình học tập.</p><div class="role-select"><button class="${state.role==='student'?'active':''}" data-action="role" data-id="student">${icon('book')}Tôi là học sinh</button><button class="${state.role==='teacher'?'active':''}" data-action="role" data-id="teacher">${icon('users')}Tôi là giáo viên</button></div><form id="login-form">${field('Tên đăng nhập','username','','text','required autocomplete="username" maxlength="80"')}${field('Mật khẩu','password','','password','required autocomplete="current-password" maxlength="200"')}<button class="primary" type="submit">Đăng nhập ${icon('arrow')}</button><div id="login-error"></div></form><div class="login-footnote">Tài khoản học sinh do giáo viên cung cấp.<br>Quên mật khẩu? Hãy liên hệ giáo viên của bạn.</div><div class="login-trust">${icon('shield')} Dữ liệu học tập riêng biệt cho từng học sinh</div></div></section></main>`;
}
function art(){return `<div class="hero-art" aria-hidden="true"><div class="art-sheet"><div class="art-check">${icon('check')}</div><span></span><span></span><span></span><span></span></div><div class="art-dot">${icon('spark')}</div></div>`;}
function navigation(){return state.user.role==='teacher'?[['overview','home','Tổng quan'],['documents','folder','Tài liệu giảng dạy'],['questions','book','Ngân hàng bài tập'],['assignments','file','Đề & giao bài'],['students','users','Học sinh'],['analytics','chart','Theo dõi học tập'],['history','clock','Lịch sử làm bài']]:[['overview','home','Tổng quan'],['learning','book','Không gian luyện tập'],['assignments','file','Bài được giao'],['review','target','Ôn tập cá nhân'],['analytics','chart','Tiến bộ của tôi'],['history','clock','Lịch sử làm bài']];}
function shell(){
 const u=state.user,items=navigation(),current=items.find(n=>n[0]===state.page)?.[2]||(state.page==='attempt'?'Làm bài':'Tài khoản');
 app.innerHTML=`<aside class="sidebar"><a class="brand" href="#overview"><span class="brand-icon">${icon('book')}</span>BTVN<span class="pill">AI</span></a><div class="brand-caption">Học từng bước, hiểu thật sâu</div><div class="eyebrow">${u.role==='teacher'?'KHÔNG GIAN GIÁO VIÊN':'GÓC HỌC TẬP'}</div><nav>${items.map(([id,ic,label])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}">${icon(ic)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('spark')}<strong>${u.role==='teacher'?'Thầy cô dẫn đường':'Mỗi người một nhịp học'}</strong>${u.role==='teacher'?'AI hỗ trợ tạo bài. Thầy cô kiểm tra và quyết định nội dung xuất bản.':'Đừng ngại dùng gợi ý. Hiểu cách giải quan trọng hơn một đáp án đúng.'}</div><button class="nav-item ${state.page==='account'?'active':''}" data-page="account">${icon('settings')}Tài khoản & bảo mật</button><div class="profile"><div class="avatar">${e(u.name.split(' ').map(v=>v[0]).slice(-2).join(''))}</div><div><strong>${e(u.name)}</strong><small>${u.role==='teacher'?'Giáo viên':e(u.class_name)}</small></div><button data-action="logout" aria-label="Đăng xuất">${icon('logout')}</button></div></div></aside><div class="mobile-shade" data-action="menu"></div><main class="main"><header class="topbar"><div class="topbar-left"><button class="icon-button mobile-menu" data-action="menu" aria-label="Mở menu">${icon('menu')}</button><div class="breadcrumb">Không gian ${u.role==='teacher'?'giảng dạy':'học tập'} &nbsp; / &nbsp; <strong>${e(current)}</strong></div></div><div class="topbar-right"><span class="date">${new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long'})}</span><button class="icon-button" data-action="theme" aria-label="Chuyển sáng hoặc tối">${icon('sun')}</button><div class="avatar">${e(u.name.trim().slice(0,1))}</div></div></header><div class="content" id="content"><div class="loading">Đang tải…</div></div></main>`;
}
async function navigate(page){
 if(!state.user)return renderLogin();if(state.user.must_change)page='account';state.page=page;shell();
 try {
  if(page==='overview')await overview();else if(page==='students')await students();else if(page==='documents')await documents();else if(page==='questions')await questions();else if(page==='assignments')await assignments();else if(page==='learning')await learning();else if(page==='review'){await review();await showRecommendations();}else if(page==='analytics')await analytics();else if(page==='history')await history();else if(page==='account')account();else if(page==='attempt'&&state.attempt)await renderAttempt();else await overview();
 }catch(error){$('#content').innerHTML=`<div class="error">${e(error.message)}</div>`;}
}
const stat=(label,value,sub,ic)=>`<div class="stat"><div class="stat-top">${e(label)}<span class="stat-icon">${icon(ic)}</span></div><strong class="stat-value">${e(value)}</strong><small>${e(sub)}</small></div>`;
function trend(data){const days=data.timeline.slice(-7);return days.length?`<div class="week-chart">${days.map(day=>{const graded=day.total-day.pending,percent=graded?Math.round(day.right/graded*100):0;return `<div class="bar-group"><div class="bar-track"><div class="bar-fill" data-height="${percent}"></div></div><strong>${percent}%</strong><p>${e(day.date.slice(5))}</p></div>`;}).join('')}</div><p class="subtext">Tỷ lệ đúng theo lượt đã chấm · Độ khó từng giai đoạn có thể khác nhau.</p>`:empty('Biểu đồ sẽ xuất hiện khi có kết quả làm bài.');}
async function overview(){
 const isTeacher=state.user.role==='teacher';const [data,assignmentList]=await Promise.all([api('analytics'),api('assignments')]);state.analytics=data;
 const qs=isTeacher?await api('questions'):await api('catalog');state.catalog=qs;
 const graded=data.rows.filter(r=>r.correct!==null),right=graded.filter(r=>r.correct===1).length,rate=graded.length?Math.round(right/graded.length*100)+'%':'—';
 const lessons=[...new Map(qs.filter(q=>!isTeacher||q.status==='published').map(q=>[q.subject+'|'+q.lesson,{subject:q.subject,lesson:q.lesson,type:q.type}])).values()];
 const risks=data.groups.filter(g=>g.risk);const suggestions=data.groups.filter(g=>g.rate!==null&&g.rate<80).slice(0,3);
 $('#content').innerHTML=title(`Chào ${state.user.name.split(' ').slice(-1)[0]}, ${isTeacher?'cùng dẫn dắt việc học':'hôm nay mình học gì'}?`,isTeacher?'Mọi tiến bộ của học sinh, trong một không gian.':'Mỗi bài tập là một bước tiến. Hãy bắt đầu từ điều em muốn hiểu rõ hơn.')+`<section class="hero"><div><span class="eyebrow">${isTeacher?'DẠY TỪ TÀI LIỆU CỦA BẠN':'HỌC THEO CÁCH CỦA EM'}</span><h2>${isTeacher?'Từ trang tài liệu,<br>đến những giờ học hiệu quả.':'Từng bước hiểu bài.<br>Tự tin chinh phục kiến thức.'}</h2><p>${isTeacher?'Tạo bài tập với AI, kiểm duyệt theo phương pháp của thầy cô và theo sát từng học sinh.':'Luyện tập vừa sức, mở gợi ý khi cần và tìm ra cách giải bằng chính suy nghĩ của mình.'}</p><button class="primary" data-page="${isTeacher?'documents':'learning'}">${isTeacher?'Mở tài liệu giảng dạy':'Bắt đầu luyện tập'} ${icon('arrow')}</button></div>${art()}</section><section class="stats">${stat(isTeacher?'Học sinh':'Bài tập sẵn sàng',isTeacher?data.students.length:qs.length,isTeacher?'Trong phạm vi quản lý':'Được giáo viên phê duyệt',isTeacher?'users':'book')}${stat(isTeacher?'Bài tập đã xuất bản':'Câu đã trả lời',isTeacher?qs.filter(q=>q.status==='published').length:data.rows.length,isTeacher?'Sẵn sàng cho học sinh':'Mỗi câu là một lần học','check')}${stat('Tỷ lệ trả lời đúng',rate,`${graded.length} lượt đã có kết luận`,'target')}${stat(isTeacher?'Dạng bài cần chú ý':'Bài được giao',isTeacher?risks.length:assignmentList.filter(a=>a.attempt_status!=='submitted').length,isTeacher?'Có ít nhất 5 câu đã chấm':'Bao gồm luyện tập và kiểm tra',isTeacher?'chart':'file')}</section><div class="dashboard-grid"><div class="stack"><section class="card"><div class="section-title"><h2>${isTeacher?'Nội dung đang giảng dạy':'Tiếp tục hành trình'}</h2><button class="text-button" data-page="${isTeacher?'questions':'learning'}">Xem tất cả →</button></div>${lessons.slice(0,4).map(l=>`<div class="course"><div class="course-icon">${icon('book')}</div><div class="course-text"><h3>${e(l.lesson)}</h3><p>${e(l.subject)} · ${qs.filter(q=>q.lesson===l.lesson&&q.subject===l.subject).length} bài tập</p></div><button class="secondary" data-page="${isTeacher?'questions':'learning'}">${isTeacher?'Quản lý':'Khám phá'} →</button></div>`).join('')||empty('Chưa có bài học. Giáo viên hãy tải tài liệu và xuất bản bài tập.')}</section><section class="card"><div class="section-title"><h2>Nhịp học theo thời gian</h2>${badge('7 ngày có hoạt động gần nhất','gray')}</div>${trend(data)}</section></div><div class="stack"><section class="card"><div class="row between"><h2>${isTeacher?'Điểm cần đồng hành':'Gợi ý cho riêng em'}</h2>${icon('spark')}</div><p class="subtext">${isTeacher?'Tín hiệu từ kết quả học tập, giúp thầy cô hỗ trợ đúng lúc.':'Dựa trên kết quả đã chấm và mức sử dụng gợi ý.'}</p>${(isTeacher?risks:suggestions).slice(0,3).map(g=>`<div class="recommendation">${badge(isTeacher?'Cần chú ý':'Nên ôn thêm','gold')}<h3>${e(isTeacher?g.student:g.type)}</h3><p>${e(g.lesson)} · ${g.rate}% đúng / ${g.right+g.wrong} câu</p><button class="text-button" data-page="${isTeacher?'analytics':'review'}">${isTeacher?'Xem chi tiết':'Ôn tập ngay'} →</button></div>`).join('')||`<div class="notice">${data.rows.length?'Chưa có dạng bài cần cảnh báo. Tiếp tục theo dõi theo thời gian.':'Chưa đủ dữ liệu để đề xuất. Kết quả từ những bài đầu tiên sẽ giúp cá nhân hóa việc học.'}</div>`}</section><section class="card"><span class="eyebrow">${isTeacher?'QUY TRÌNH KIỂM DUYỆT':'HỌC CHỦ ĐỘNG'}</span><h3 class="spacer">${isTeacher?'AI hỗ trợ. Thầy cô quyết định.':'Chưa đúng cũng là một cơ hội.'}</h3><p class="subtext">${isTeacher?'Bản nháp → Kiểm tra → Phê duyệt → Xuất bản. Mỗi bài tập đều có nguồn và phiên bản rõ ràng.':'Hãy thử tự giải trước, sau đó mở từng gợi ý. Những câu chưa đúng sẽ trở thành bài ôn của riêng em.'}</p></section></div></div>`;
 applyBars();
}
function applyBars(){document.querySelectorAll('[data-height]').forEach(el=>el.style.height=el.dataset.height+'%');}
async function showRecommendations(){
 const result=await api('recommendations');let container=$('#ai-recommendations');
 if(!container){container=document.createElement('section');container.id='ai-recommendations';container.className='card spacer';$('#content').append(container);}
 container.innerHTML=`<div class="section-title"><h2>${icon('spark')} Đề xuất ôn tập từ AI</h2><button class="secondary small" data-action="ai-suggest">Phân tích kết quả của em</button></div><p class="subtext">AI chỉ nhận số liệu ẩn danh của chính em, không nhận tên hoặc tài khoản. Cần tối thiểu 5 câu đã chấm trong một dạng bài.</p>${result.items.length?result.items.map(g=>`<div class="recommendation"><h3>${e(g.type)}</h3><p>${e(g.subject)} → ${e(g.lesson)} · ${g.rate}% đúng</p><p>${e(g.reason)}</p><button class="text-button" data-action="adaptive" data-subject="${e(g.subject)}" data-lesson="${e(g.lesson)}" data-type="${e(g.type)}">Luyện dạng này →</button></div>`).join('')+`<p class="subtext">Đề xuất lưu lúc ${date(result.created_at)}. Cập nhật phân tích khi có thêm kết quả.</p>`:'<div class="notice">Chưa có đề xuất AI. Có thể tiếp tục luyện tập theo thống kê phía trên.</div>'}`;
}
async function students(){state.students=await api('students');$('#content').innerHTML=title('Học sinh','Tài khoản riêng, tiến độ riêng, sự quan tâm dành cho từng em.',`<button class="primary" data-action="new-student">${icon('plus')}Thêm học sinh</button>`)+`<div class="card"><div class="filters"><input id="student-search" placeholder="Tìm theo tên, tài khoản hoặc lớp…" aria-label="Tìm học sinh"></div><div id="student-table"></div></div>`;studentTable();}
function studentTable(){const query=($('#student-search')?.value||'').toLowerCase();const list=state.students.filter(s=>(s.name+s.username+s.class_name).toLowerCase().includes(query));$('#student-table').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr><th>HỌC SINH</th><th>TÀI KHOẢN</th><th>LỚP</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody>${list.map(s=>`<tr><td><strong>${e(s.name)}</strong></td><td>${e(s.username)}</td><td>${e(s.class_name)}</td><td>${badge(s.locked?'Đã khóa':s.must_change?'Cần đổi mật khẩu':'Đang hoạt động',s.locked?'red':s.must_change?'gold':'')}</td><td><div class="row">${btn('Sửa','edit-student',s.id)}${btn('Cấp mật khẩu','reset-student',s.id)}${btn(s.locked?'Mở khóa':'Khóa','lock-student',s.id)}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có học sinh phù hợp.');}
function studentModal(s){showModal(s?'Sửa thông tin học sinh':'Tạo tài khoản học sinh',`<form id="student-form" data-id="${s?.id||''}">${field('Họ và tên','name',s?.name||'','text','required maxlength="120"')}${!s?field('Tên đăng nhập (không dấu)','username','','text','required pattern="[a-zA-Z0-9._-]+" maxlength="60" autocomplete="off"'):''}${field('Lớp','class_name',s?.class_name||'Lớp 8A','text','required maxlength="80"')}${!s?field('Mật khẩu tạm thời','password','','password','required minlength="10" maxlength="200" autocomplete="new-password"'):''}<p class="subtext">Học sinh phải đổi mật khẩu tạm thời khi đăng nhập lần đầu.</p>${buttons(s?'Lưu thay đổi':'Tạo tài khoản')}</form>`);}
async function documents(){state.documents=await api('documents');$('#content').innerHTML=title('Tài liệu giảng dạy','Nền tảng kiến thức và phương pháp cho mọi bài tập.',`<button class="primary" data-action="upload">${icon('upload')}Thêm tài liệu</button>`)+(!state.ai?`<div class="notice warning">Chưa cấu hình AI. Bạn vẫn có thể tải tài liệu, nhập phân tích và tạo bài tập thủ công. Hướng dẫn cấu hình nằm trong README của repo.</div><br>`:'')+`<div class="grid two">${state.documents.map(doc=>`<article class="card"><div class="row between"><span class="stat-icon">${icon('file')}</span>${badge(slabel[doc.status],doc.status==='confirmed'?'':'gold')}</div><h3 class="spacer">${e(doc.title)}</h3><p class="subtext">${e(doc.filename||'Văn bản nhập trực tiếp')} · ${date(doc.created_at)}</p><div class="row wrap">${btn('Xem & xác nhận','view-doc',doc.id)}${btn('AI phân tích','analyze-doc',doc.id)}</div></article>`).join('')}</div>`+(state.documents.length?'':empty('Thêm PDF, Word hoặc văn bản để bắt đầu.'));}
function uploadModal(){showModal('Thêm tài liệu giảng dạy',`<form id="upload-form">${field('Tên tài liệu','title','','text','required maxlength="200"')}<div class="field"><label for="doc-file">Chọn tệp PDF, Word hoặc TXT</label><input id="doc-file" name="file" type="file" accept=".pdf,.docx,.txt"><small>Tối đa 30 MB. PDF quét cần OCR trước. Công thức và bảng cần giáo viên kiểm tra lại sau trích xuất.</small></div>${area('Hoặc dán nội dung văn bản','content','','maxlength="300000"')}<div class="notice">Nội dung được lưu riêng trong phạm vi của giáo viên.</div>${buttons('Lưu tài liệu')}</form>`);}
async function docModal(id){const doc=await api('documents/'+id);const a=doc.analysis;showModal('Kiểm tra & xác nhận tài liệu',`<p><strong>${e(doc.title)}</strong></p><details><summary>Xem nội dung đã trích xuất</summary><div class="source"><pre class="question-prompt">${e(doc.content)}</pre></div></details><br><form id="document-confirm" data-id="${doc.id}">${area('Lý thuyết chính','theory',a.theory||'','required maxlength="18000"')}${area('Các dạng bài (mỗi dòng một dạng)','types',(a.types||[]).join('\n'),'required')}${area('Các bước giải theo phương pháp giáo viên (mỗi dòng một bước)','steps',(a.steps||[]).join('\n'),'required')}${a.conflicts?.length?`<div class="notice warning">${e(a.conflicts.join('\n'))}</div>`:''}<p class="subtext">Chỉ xác nhận sau khi kiểm tra công thức, nội dung và phương pháp.</p>${buttons('Xác nhận phân tích')}</form>`);}
async function questions(){[state.questions,state.documents]=await Promise.all([api('questions'),api('documents')]);$('#content').innerHTML=title('Ngân hàng bài tập','Tạo, kiểm tra và xuất bản nội dung theo phương pháp của bạn.',`<div class="row wrap"><button class="secondary" data-action="new-question">${icon('plus')}Nhập bài tập</button><button class="primary" data-action="generate">${icon('spark')}Tạo với AI</button></div>`)+`<div class="filters"><input id="question-search" placeholder="Tìm nội dung, bài học, dạng bài…" aria-label="Tìm bài tập"><select id="question-status" aria-label="Lọc trạng thái"><option value="">Mọi trạng thái</option>${Object.entries(slabel).slice(0,4).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select><select id="question-difficulty" aria-label="Lọc độ khó"><option value="">Mọi độ khó</option>${Object.entries(dlabel).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></div><div id="question-list"></div>`;questionList();}
function questionList(){const search=($('#question-search')?.value||'').toLowerCase(),status=$('#question-status')?.value,difficulty=$('#question-difficulty')?.value;const list=state.questions.filter(q=>(!search||(q.prompt+q.lesson+q.type).toLowerCase().includes(search))&&(!status||q.status===status)&&(!difficulty||q.difficulty===difficulty));$('#question-list').innerHTML=list.length?`<div class="grid two">${list.map(q=>`<article class="card question-card"><div class="row between"><div class="tag-row">${badge(dlabel[q.difficulty],q.difficulty==='hard'?'gold':'')}${badge('v'+q.version,'gray')}</div>${badge(slabel[q.status],q.status==='draft'?'gold':'')}</div><small>${e(q.subject)} / ${e(q.lesson)} / ${e(q.type)}</small><h3>${e(q.prompt)}</h3>${q.duplicates.length?`<div class="notice warning">Có ${q.duplicates.length} câu tương tự. Cần kiểm tra trước khi duyệt.</div>`:''}<div class="row wrap">${btn('Xem / sửa','edit-question',q.id)}${q.status==='draft'?btn('Phê duyệt','approve-question',q.id,true):q.status==='approved'?btn('Xuất bản','publish-question',q.id,true):q.status==='published'?btn('Ngừng sử dụng','retire-question',q.id):''}</div></article>`).join('')}</div>`:empty('Chưa có bài tập phù hợp. Thêm tài liệu rồi nhập bài hoặc tạo bằng AI.');}
function questionModal(q){if(!state.documents.length)return toast('Hãy thêm tài liệu nguồn trước.');const source=q?.sources?.[0];showModal(q?'Nội dung & phiên bản mới':'Nhập bài tập mới',`<form id="question-form" data-id="${q?.id||''}"><div class="grid two compact">${field('Môn học','subject',q?.subject||'Toán học','text','required')}${field('Bài học','lesson',q?.lesson||'','text','required')}</div>${field('Dạng bài','type',q?.type||'','text','required')}<div class="grid two compact">${select('Độ khó','difficulty',Object.entries(dlabel),q?.difficulty||'medium')}${select('Kiểu đáp án','kind',[['number','Đáp án số'],['choice','Trắc nghiệm'],['text','Tự luận ngắn']],q?.kind||'number')}</div>${area('Đề bài','prompt',q?.prompt||'','required maxlength="8000"')}${area('Lựa chọn trắc nghiệm (mỗi dòng một lựa chọn)','options',(q?.options||[]).join('\n'))}<div class="grid two compact">${field('Đáp án chuẩn','answer',q?.answer||'','text','required')}${field('Sai số cho đáp án số','tolerance',q?.tolerance||0,'number','min="0" max="100" step="any"')}</div>${area('Lời giải theo phương pháp giáo viên','solution',q?.solution||'','required maxlength="12000"')}${area('Gợi ý (mỗi dòng một bước)','hints',(q?.hints||[]).join('\n'),'required')}${select('Tài liệu nguồn','documentId',state.documents.map(d=>[d.id,d.title]),source?.documentId||'')}${field('Vị trí trong tài liệu','location',source?.location||'Đoạn 1','text','required')}${area('Trích dẫn nguyên văn từ tài liệu','quote',source?.quote||'','required')}<p class="subtext">${q?'Lưu sẽ tạo bản nháp phiên bản mới; lịch sử và đề cũ được bảo toàn.':'Bài tập mới được lưu ở trạng thái bản nháp.'} Tự luận cần giáo viên chấm. Biểu thức chưa hỗ trợ chấm tương đương tự động.</p>${q?`<details><summary>Đối chiếu câu tương tự và nguồn hiện tại</summary>${q.duplicates.map(d=>`<p class="subtext">#${d.id} · ${d.score}% · ${e(d.prompt)}</p>`).join('')}${q.sources.map(s=>`<div class="source">Tài liệu #${s.documentId} · ${e(s.location)}<blockquote>${e(s.quote)}</blockquote></div>`).join('')}</details>`:''}${buttons(q?'Lưu phiên bản mới':'Lưu bản nháp')}</form>`);}
function generateModal(){const docs=state.documents.filter(d=>d.status==='confirmed');if(!docs.length)return toast('Cần ít nhất một tài liệu đã xác nhận phân tích.');showModal('Tạo bài tập với AI',`<form id="generate-form"><div class="field"><label>Tài liệu nguồn (chọn 1–5 tài liệu)</label><div class="document-list">${docs.map(doc=>`<label class="check"><input type="checkbox" name="documentIds" value="${doc.id}">${e(doc.title)}</label>`).join('')}</div></div>${field('Môn học','subject','Toán học','text','required')}${field('Bài học','lesson','','text','required')}${field('Dạng bài','type','','text','required')}<div class="grid two compact">${field('Số lượng','count',5,'number','min="1" max="20" required')}${select('Độ khó','difficulty',Object.entries(dlabel),'medium')}</div><div class="notice">AI có thể cần đến 90 giây. Kết quả luôn là bản nháp; thầy cô kiểm tra và phê duyệt trước khi xuất bản.</div>${buttons('Tạo bản nháp')}</form>`);}
async function assignments(){const items=await api('assignments'),teacher=state.user.role==='teacher';$('#content').innerHTML=title(teacher?'Đề & giao bài':'Bài được giao',teacher?'Đề ngẫu nhiên từ ngân hàng đã duyệt, mỗi học sinh một phiên bản cố định.':'Kiểm tra thời gian, chuẩn bị sẵn sàng và làm bài theo nhịp của mình.',teacher?`<button class="primary" data-action="new-assignment">${icon('plus')}Tạo & giao đề</button>`:'')+`<div class="grid two">${items.map(x=>`<article class="card"><div class="row between"><span class="stat-icon">${icon(x.mode==='exam'?'clock':'book')}</span>${badge(x.mode==='exam'?'Kiểm tra':'Luyện tập',x.mode==='exam'?'gold':'')}</div><h3 class="spacer">${e(x.title)}</h3><p class="subtext">${x.mode==='exam'?x.minutes+' phút':'Không giới hạn thời lượng'} · ${teacher?x.student_count+' học sinh':x.count+' câu hỏi'}<br>Mở: ${date(x.opens_at)} · Đóng: ${date(x.closes_at)}</p><div class="row between">${badge(x.release==='after_close'?'Kết quả sau khi đóng đề':'Kết quả theo lượt nộp','gray')}${teacher?'':btn(x.attempt_status==='submitted'?'Xem kết quả':x.attempt_id?'Tiếp tục':'Bắt đầu','start',x.student_assignment_id,true)}</div></article>`).join('')}</div>`+(items.length?'':empty('Chưa có bài được giao.'));}
async function assignmentModal(){const [students,questions]=await Promise.all([api('students'),api('questions')]);const published=questions.filter(q=>q.status==='published');if(!students.length||!published.length)return toast('Cần có học sinh và bài tập đã xuất bản trước khi giao đề.');const distinct=key=>[['','Tất cả'],...[...new Set(published.map(q=>q[key]))].map(v=>[v,v])];showModal('Tạo đề & giao cho học sinh',`<form id="assignment-form">${field('Tên đề','title','','text','required maxlength="200"')}<div class="grid two compact">${select('Chế độ','mode',[['practice','Luyện tập'],['exam','Kiểm tra có thời gian']])}${field('Thời lượng kiểm tra (phút)','minutes',30,'number','min="1" max="240"')}</div><div class="grid two compact">${select('Môn học','subject',distinct('subject'))}${select('Bài học','lesson',distinct('lesson'))}</div><div class="grid two compact">${select('Dạng bài','type',distinct('type'))}${select('Độ khó','difficulty',[['','Tất cả'],...Object.entries(dlabel)])}</div>${field('Số câu','count',5,'number',`min="1" max="100" required`)}<p class="subtext">Có ${published.length} câu đã xuất bản. Hệ thống báo lỗi nếu bộ lọc không đủ câu.</p><div class="grid two compact">${field('Mở đề (không bắt buộc)','opens_at','','datetime-local')}${field('Đóng đề (không bắt buộc)','closes_at','','datetime-local')}</div>${select('Công bố kết quả kiểm tra','release',[['immediate','Sau khi học sinh kết thúc'],['after_close','Sau thời gian đóng đề']])}<label class="check"><input name="variants" type="checkbox" checked>Tạo phiên bản ngẫu nhiên riêng cho từng học sinh</label><label class="check"><input name="allow_hints" type="checkbox">Cho phép gợi ý khi kiểm tra (luyện tập luôn có gợi ý)</label><div class="field spacer"><label>Học sinh nhận đề</label><div class="document-list">${students.filter(s=>!s.locked).map(s=>`<label class="check"><input type="checkbox" name="studentIds" value="${s.id}" checked>${e(s.name)} · ${e(s.class_name)}</label>`).join('')}</div></div>${buttons('Tạo & giao đề')}</form>`);}
async function learning(){state.catalog=await api('catalog');const list=state.catalog;const opts=key=>`<option value="">Tất cả ${key==='subject'?'môn':key==='lesson'?'bài học':'dạng bài'}</option>${[...new Set(list.map(q=>q[key]))].map(v=>`<option value="${e(v)}">${e(v)}</option>`).join('')}`;$('#content').innerHTML=title('Không gian luyện tập','Chọn bài học, mở từng dạng bài và luyện theo nhịp của em.')+`<div class="filters"><input id="catalog-search" placeholder="Tìm nội dung bài tập…" aria-label="Tìm bài tập"><select id="catalog-subject" aria-label="Môn học">${opts('subject')}</select><select id="catalog-lesson" aria-label="Bài học">${opts('lesson')}</select><select id="catalog-type" aria-label="Dạng bài">${opts('type')}</select><select id="catalog-difficulty" aria-label="Độ khó"><option value="">Mọi độ khó</option>${Object.entries(dlabel).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></div><div id="catalog-list"></div>`;catalogList();}
function catalogList(){const query=($('#catalog-search')?.value||'').toLowerCase();const list=state.catalog.filter(q=>(!query||(q.prompt+q.subject+q.lesson+q.type).toLowerCase().includes(query))&&['subject','lesson','type','difficulty'].every(k=>!$('#catalog-'+k)?.value||q[k]===$('#catalog-'+k).value));const groups=[...new Set(list.map(q=>q.subject+'|'+q.lesson+'|'+q.type))];$('#catalog-list').innerHTML=groups.length?groups.map(key=>{const [subject,lesson,type]=key.split('|');const qs=list.filter(q=>q.subject===subject&&q.lesson===lesson&&q.type===type);return `<section class="card spacer"><div class="section-title"><div><span class="eyebrow">${e(subject)} → ${e(lesson)}</span><h2 class="spacer">${e(type)}</h2></div><button class="primary small" data-action="adaptive" data-subject="${e(subject)}" data-lesson="${e(lesson)}" data-type="${e(type)}">${icon('spark')}Luyện theo năng lực</button></div><div class="grid two">${qs.map(q=>`<article class="recommendation"><div class="row between">${badge(dlabel[q.difficulty])}<small>#${q.id}</small></div><h3>${e(q.prompt)}</h3><div class="row between"><span class="subtext">${q.totalHints} bước gợi ý</span>${btn('Làm bài →','practice',q.id)}</div></article>`).join('')}</div></section>`;}).join(''):empty('Không có bài tập phù hợp. Hãy thử thay đổi bộ lọc.');}
async function review(){const data=await api('analytics');state.analytics=data;const wrong=data.rows.filter(r=>r.correct===0);$('#content').innerHTML=title('Ôn tập dành riêng cho em','Quay lại câu đã sai, hiểu điều chưa rõ và thử thêm một lần.',wrong.length?btn('Tạo bài ôn từ câu sai','review-start','',true):'')+`<div class="notice">Bài ôn dùng câu đã được giáo viên duyệt. Đề xuất chỉ hình thành khi có đủ dữ liệu; không có đánh giá cố định về năng lực.</div><div class="grid two spacer">${data.groups.map(g=>`<article class="card"><div class="row between">${badge(g.right+g.wrong>=5?'Đủ dữ liệu ban đầu':'Đang tìm hiểu nhịp học','gray')}${badge(g.rate===null?'Chưa chấm':g.rate+'% đúng',g.rate<50?'gold':'')}</div><h3 class="spacer">${e(g.type)}</h3><p class="subtext">${e(g.subject)} → ${e(g.lesson)}<br>${g.right} đúng · ${g.wrong} sai · ${g.pending} chờ chấm · ${g.hints} bước gợi ý</p><p class="subtext">${e(g.reason)}</p><button class="primary small" data-action="adaptive" data-subject="${e(g.subject)}" data-lesson="${e(g.lesson)}" data-type="${e(g.type)}">Luyện ${dlabel[g.level].toLowerCase()} ${icon('arrow')}</button></article>`).join('')}</div>`+(data.groups.length?'':empty('Hãy làm một vài bài tập trước. Góc ôn tập của em sẽ dần được hình thành.'));}
async function analytics(){const data=await api('analytics');state.analytics=data;const teacher=state.user.role==='teacher';$('#content').innerHTML=title(teacher?'Theo dõi học tập':'Tiến bộ của tôi',teacher?'Nhìn rõ kết quả, mức dùng gợi ý và những dạng bài cần đồng hành.':'Theo dõi sự tiến bộ từ những lần thử, không chỉ từ điểm số.')+`<div class="stats">${stat('Lượt trả lời',data.rows.length,'Bao gồm câu đang chờ chấm','book')}${stat('Câu đúng',data.rows.filter(r=>r.correct===1).length,'Theo lượt đã có kết luận','check')}${stat('Bước gợi ý',data.rows.reduce((n,r)=>n+r.hints,0),'Mỗi bước trong một lượt chỉ tính một lần','spark')}${stat('Dạng cần chú ý',data.groups.filter(g=>g.risk).length,'Tối thiểu 5 câu đã chấm','target')}</div><section class="card"><h2>Tiến bộ theo thời gian</h2>${trend(data)}</section><section class="card spacer"><h2>Kết quả theo bài học & dạng bài</h2><div class="filters">${teacher?`<select id="analytics-student" aria-label="Chọn học sinh"><option value="">Tất cả học sinh</option>${data.students.map(s=>`<option value="${s.id}">${e(s.name)}</option>`).join('')}</select>`:''}<input type="date" id="analytics-from" aria-label="Từ ngày"><input type="date" id="analytics-to" aria-label="Đến ngày"></div><p class="subtext">Tỷ lệ đúng theo lượt đã chấm. Câu chờ chấm được tách riêng. Thay đổi độ khó cần được xem cùng kết quả.</p><div id="analytics-table"></div></section><section class="card spacer"><h2>Bối cảnh từng giai đoạn</h2><div class="table-wrap"><table><thead><tr><th>NGÀY (UTC)</th><th>DỄ / VỪA / KHÓ</th><th>ĐÚNG / ĐÃ CHẤM</th><th>GỢI Ý</th><th>THỜI GIAN LÀM</th></tr></thead><tbody>${data.timeline.map(t=>`<tr><td>${e(t.date)}</td><td>${t.easy} / ${t.medium} / ${t.hard}</td><td>${t.right} / ${t.total-t.pending}</td><td>${t.hints}</td><td>${Math.round(t.seconds/60)} phút</td></tr>`).join('')}</tbody></table></div></section>`;analyticsTable();applyBars();}
function analyticsTable(){const student=$('#analytics-student')?.value,from=$('#analytics-from')?.value,to=$('#analytics-to')?.value;let rows=state.analytics.rows.filter(r=>(!student||r.student_id===Number(student))&&(!from||new Date(r.started_at).toISOString().slice(0,10)>=from)&&(!to||new Date(r.started_at).toISOString().slice(0,10)<=to));const groups=new Map();for(const r of rows){const key=[r.student_id,r.subject,r.lesson,r.type].join('|');const g=groups.get(key)||{...r,total:0,right:0,wrong:0,pending:0,hints:0};g.total++;if(r.correct===null)g.pending++;else if(r.correct)g.right++;else g.wrong++;g.hints+=r.hints;groups.set(key,g);}$('#analytics-table').innerHTML=groups.size?`<div class="table-wrap"><table><thead><tr><th>HỌC SINH</th><th>BÀI / DẠNG</th><th>ĐÚNG / SAI / CHỜ</th><th>TỶ LỆ ĐÚNG</th><th>GỢI Ý</th><th>QUAN SÁT</th></tr></thead><tbody>${[...groups.values()].map(g=>{const n=g.right+g.wrong,rate=n?Math.round(g.right/n*100):null;return `<tr><td>${e(state.analytics.students.find(s=>s.id===g.student_id)?.name)}</td><td class="question-cell">${e(g.subject)} → ${e(g.lesson)}<br><strong>${e(g.type)}</strong></td><td>${g.right} / ${g.wrong} / ${g.pending}</td><td>${rate===null?'—':rate+'%'} <small>(${n} lượt)</small></td><td>${g.hints}</td><td>${badge(n<5?'Chưa đủ dữ liệu':rate<50?'Cần theo dõi':'Tiếp tục luyện',n>=5&&rate<50?'gold':'gray')}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Chưa có dữ liệu trong khoảng đã chọn.');}
async function history(){const list=await api('history');const teacher=state.user.role==='teacher';$('#content').innerHTML=title('Lịch sử làm bài','Đối chiếu từng lượt, câu trả lời và gợi ý đã sử dụng.')+`<div class="card">${list.length?`<div class="table-wrap"><table><thead><tr>${teacher?'<th>HỌC SINH</th>':''}<th>BÀI LÀM</th><th>THỜI ĐIỂM</th><th>KẾT QUẢ</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${list.map(a=>`<tr>${teacher?`<td>${e(a.student)}</td>`:''}<td>${e(a.title)}</td><td>${date(a.started_at)}</td><td>${a.graded_count===null?'Chưa công bố':a.right_count+' / '+a.graded_count+' đã chấm'+(a.pending_count?' · '+a.pending_count+' chờ':'')}</td><td>${badge(a.status==='active'?'Đang làm':'Đã nộp',a.status==='active'?'gold':'')}</td><td>${btn('Xem chi tiết',teacher?'teacher-attempt':'open-attempt',a.id)}</td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có lượt làm bài nào.')}</div>`;}
async function teacherAttempt(id){const a=await api('attempts/'+id);showModal(a.title,`<div class="stack">${a.questions.map((q,i)=>`<section class="card"><small>Câu ${i+1} · ${e(q.type)} · ${dlabel[q.difficulty]}</small><h3>${e(q.prompt)}</h3><div class="review-answer">Đáp án học sinh: ${e(q.answer?.response??q.answer?.draft??'Chưa trả lời')}</div><div class="subtext">Đáp án chuẩn: ${e(q.expected||'—')}<br>Gợi ý đã mở: ${q.hints.length} bước</div><p class="subtext">${e(q.answer?.feedback||'')}</p>${q.kind==='text'&&q.answer?.response!==null&&q.answer?`<form class="grade-form" data-attempt="${a.id}" data-question="${q.id}">${select('Kết quả','correct',[['1','Đúng'],['0','Chưa đúng']],q.answer.correct===1?'1':'0')}${area('Nhận xét của giáo viên','feedback',q.answer.feedback||'','required')}<button class="primary small">Lưu đánh giá</button></form>`:''}</section>`).join('')}</div>`);}
function account(){const forced=state.user.must_change;$('#content').innerHTML=title('Tài khoản & bảo mật','Bảo vệ không gian học tập của riêng bạn.')+`<div class="grid two"><section class="card"><h2>Thông tin tài khoản</h2><p><strong>${e(state.user.name)}</strong></p><p class="subtext">Tên đăng nhập: ${e(state.user.username)}<br>Vai trò: ${state.user.role==='teacher'?'Giáo viên':'Học sinh'}${state.user.role==='student'?'<br>Lớp: '+e(state.user.class_name):''}</p><div class="notice">${forced?'Bạn đang sử dụng mật khẩu tạm thời. Hãy đổi mật khẩu trước khi tiếp tục.':'Không chia sẻ mật khẩu với người khác. Học sinh có thể liên hệ giáo viên nếu cần cấp lại mật khẩu.'}</div></section><section class="card"><h2>Đổi mật khẩu</h2><form id="password-form">${field('Mật khẩu hiện tại','current','','password','required autocomplete="current-password"')}${field('Mật khẩu mới','password','','password','required minlength="10" maxlength="200" autocomplete="new-password"')}${field('Xác nhận mật khẩu mới','confirm','','password','required minlength="10" maxlength="200" autocomplete="new-password"')}<p class="subtext">Tối thiểu 10 ký tự. Các phiên đăng nhập khác sẽ được thu hồi.</p><button class="primary" type="submit">Cập nhật mật khẩu</button></form></section></div>`;}
async function start(id){const r=await api('start',{studentAssignmentId:Number(id)});state.attempt=await api('attempts/'+r.attemptId);state.index=0;await navigate('attempt');}
async function renderAttempt(){const a=state.attempt=await api('attempts/'+state.attempt.id);const i=Math.min(state.index,a.questions.length-1);state.index=i;const q=a.questions[i];const answered=q.answer?.response!==null&&q.answer;const locked=!!answered||a.status!=='active';const value=q.answer?.draft||'';state.clockOffset=a.serverTime-Date.now();$('#content').innerHTML=title(a.title,a.status==='submitted'?'Bài đã kết thúc. Kết quả hiển thị theo thời điểm giáo viên cho phép.':'Đọc kỹ đề, thử tự giải rồi dùng gợi ý nếu cần.',btn('Về bài được giao','back-assignments'))+`<div class="attempt-shell"><section class="card attempt-question"><div class="row between"><span class="step-title">CÂU ${i+1} / ${a.questions.length}</span>${badge(dlabel[q.difficulty])}</div><p class="subtext">${e(q.subject)} → ${e(q.lesson)} → ${e(q.type)}</p><div class="question-prompt">${e(q.prompt)}</div><form id="answer-form" data-question="${q.id}">${q.kind==='choice'?`<div class="answer-options">${q.options.map((option,index)=>`<label><input name="response" type="radio" value="${e(option)}" ${value===option?'checked':''} ${locked?'disabled':''} required><span>${String.fromCharCode(65+index)}. ${e(option)}</span></label>`).join('')}</div>`:`<div class="field spacer"><label for="student-response">${q.kind==='number'?'Đáp án của em':'Bài làm của em'}</label>${q.kind==='text'?`<textarea id="student-response" name="response" maxlength="10000" ${locked?'disabled':''} required>${e(value)}</textarea>`:`<input id="student-response" name="response" inputmode="decimal" value="${e(value)}" ${locked?'disabled':''} required maxlength="200">`}</div>`}<div class="row wrap">${!locked?`<button class="primary" type="submit">Nộp đáp án ${icon('check')}</button><button class="secondary" type="button" data-action="save-answer">Lưu nháp</button>`:badge(a.reveal?(q.answer?.correct===1?'Chính xác':q.answer?.correct===0?'Chưa đúng':'Chờ giáo viên chấm'):'Đã lưu đáp án',q.answer?.correct===0?'gold':'')}<small id="save-status"></small></div></form>${a.allow_hints?`<div class="spacer"><button class="text-button" data-action="hint" ${a.status!=='active'||q.hints.length>=q.totalHints?'disabled':''}>${icon('spark')} ${q.hints.length>=q.totalHints?'Đã mở hết gợi ý':'Mở gợi ý tiếp theo'} (${q.hints.length}/${q.totalHints})</button>${q.hints.map((h,j)=>`<div class="hint"><strong>Bước ${j+1}</strong><br>${e(h)}</div>`).join('')}</div>`:''}${answered&&a.reveal?`<div class="feedback ${q.answer.correct===0?'wrong':''}">${e(q.answer.feedback||'Đang chờ đánh giá.')}</div>${q.answer.correct===0?`<button class="text-button" data-action="explain">${icon('spark')}Giải thích thêm bằng AI</button>`:''}<div class="solution"><strong>Đối chiếu lời giải</strong><p>Đáp án: ${e(q.expected)}</p>${e(q.solution)}</div>`:''}<div class="question-nav"><button class="secondary small" data-action="previous" ${i===0?'disabled':''}>← Câu trước</button><button class="secondary small" data-action="next" ${i===a.questions.length-1?'disabled':''}>Câu tiếp →</button></div></section><aside class="card attempt-sidebar"><span class="eyebrow">${a.deadline?'THỜI GIAN CÒN LẠI':'LUYỆN TẬP CHỦ ĐỘNG'}</span>${a.deadline?'<div class="timer" id="timer">--:--</div>':'<h3 class="spacer">Từng câu, từng bước.</h3>'}<div class="number-grid">${a.questions.map((question,j)=>`<button data-action="goto-question" data-id="${j}" class="${j===i?'active':''} ${question.answer?.response!==null&&question.answer?'done':''}" aria-label="Câu ${j+1}">${j+1}</button>`).join('')}</div><p class="subtext spacer">Đáp án đã nộp được giữ nguyên. Mở gợi ý được ghi nhận riêng cho em.</p>${a.status==='active'?`<button class="primary" data-action="finish">Kết thúc & nộp bài</button>`:badge('Đã kết thúc')}</aside></div>`;tick();}
function tick(){const el=$('#timer');if(!el||!state.attempt)return;const a=state.attempt;if(a.status!=='active'){el.textContent='Đã kết thúc';return;}const seconds=Math.max(0,Math.ceil((a.deadline-Date.now()-state.clockOffset)/1000));el.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');if(seconds===0&&!state.finishing){state.finishing=true;api(`attempts/${a.id}/finish`,{}).then(result=>{state.attempt=result;return renderAttempt();}).catch(error=>toast(error.message)).finally(()=>state.finishing=false);}}
setInterval(tick,1000);
async function saveDraft(){const form=$('#answer-form');if(!form||state.attempt?.status!=='active')return;const data=Object.fromEntries(new FormData(form));if(data.response===undefined)return;await api(`attempts/${state.attempt.id}/save`,{questionId:Number(form.dataset.question),response:data.response});const label=$('#save-status');if(label)label.textContent='Đã lưu lúc '+new Date().toLocaleTimeString('vi-VN');const q=state.attempt.questions[state.index];q.answer={...q.answer,draft:data.response};}
let autosave;
document.addEventListener('input',event=>{if(event.target.closest('#answer-form')){clearTimeout(autosave);autosave=setTimeout(()=>saveDraft().catch(()=>{if($('#save-status'))$('#save-status').textContent='Chưa lưu được. Kiểm tra kết nối.';}),700);}if(event.target.id==='student-search')studentTable();if(event.target.id==='question-search')questionList();if(event.target.id==='catalog-search')catalogList();});
document.addEventListener('change',event=>{if(event.target.id.startsWith('question-'))questionList();if(event.target.id.startsWith('catalog-'))catalogList();if(event.target.id.startsWith('analytics-'))analyticsTable();});
document.addEventListener('click',async event=>{
 const target=event.target.closest('button,[data-action],a[href="#overview"]');if(!target)return;
 if(target.matches('a')){event.preventDefault();return navigate('overview');}
 if(target.dataset.page){clearTimeout(autosave);if(state.page==='attempt'&&state.attempt?.status==='active'){try{await saveDraft();}catch(error){toast(error.message);return;}}return navigate(target.dataset.page);}
 const action=target.dataset.action,id=target.dataset.id;if(!action)return;
 try {
  if(action==='close')return modal.close();if(action==='role'){state.role=id;return renderLogin();}if(action==='menu')return $('.sidebar').classList.toggle('open');if(action==='theme'){localStorage.setItem('btvn-theme',document.documentElement.dataset.theme==='dark'?'light':'dark');return theme();}
  target.disabled=true;
  if(action==='logout'){await api('logout',{});state.user=null;renderLogin();}
  if(action==='new-student')studentModal();
  if(action==='edit-student')studentModal(state.students.find(s=>s.id===Number(id)));
  if(action==='lock-student'){const s=state.students.find(s=>s.id===Number(id));showModal(s.locked?'Mở khóa tài khoản':'Khóa tài khoản',`<p>${e(s.name)} · ${e(s.username)}</p><p class="subtext">${s.locked?'Học sinh có thể đăng nhập lại sau khi mở khóa.':'Các phiên đang đăng nhập sẽ kết thúc ngay.'}</p><form id="lock-form" data-id="${id}">${buttons(s.locked?'Mở khóa':'Khóa tài khoản')}</form>`);}
  if(action==='reset-student')showModal('Cấp lại mật khẩu',`<form id="reset-form" data-id="${id}">${field('Mật khẩu tạm thời mới','password','','password','required minlength="10" maxlength="200" autocomplete="new-password"')}<p class="subtext">Mật khẩu cũ và các phiên hiện tại sẽ mất hiệu lực.</p>${buttons('Cấp mật khẩu')}</form>`);
  if(action==='upload')uploadModal();if(action==='view-doc')await docModal(id);
  if(action==='analyze-doc'){toast('Đang phân tích tài liệu…');await api('documents/'+id+'/analyze',{});await documents();await docModal(id);}
  if(action==='new-question')questionModal();if(action==='edit-question')questionModal(state.questions.find(q=>q.id===Number(id)));if(action==='generate')generateModal();
  if(['approve-question','publish-question','retire-question'].includes(action)){const q=state.questions.find(q=>q.id===Number(id));const act=action.split('-')[0];if(act==='approve'){showModal('Phê duyệt bài tập',`<p class="question-prompt">${e(q.prompt)}</p><p><strong>Đáp án:</strong> ${e(q.answer)}</p><p class="subtext">${e(q.solution)}</p>${q.hints.map((h,i)=>`<div class="hint">Bước ${i+1}: ${e(h)}</div>`).join('')}${q.sources.map(s=>`<div class="source">Nguồn #${s.documentId} · ${e(s.location)}<blockquote>${e(s.quote)}</blockquote></div>`).join('')}${q.duplicates.map(d=>`<div class="notice warning spacer">Tương tự câu #${d.id} (${d.score}%): ${e(d.prompt)}</div>`).join('')}<form id="approve-form" data-id="${id}"><label class="check spacer"><input name="checked" type="checkbox" required>Tôi đã kiểm tra đề, đáp án, gợi ý, nguồn và các câu tương tự.</label>${buttons('Phê duyệt phiên bản này')}</form>`);}else{await api('questions/'+id,{action:act});toast(act==='publish'?'Đã xuất bản. Học sinh có thể truy cập.':'Đã ngừng sử dụng cho đề mới.');await questions();}}
  if(action==='new-assignment')await assignmentModal();if(action==='start')await start(id);
  if(action==='practice'||action==='adaptive'||action==='review-start'){const data=action==='practice'?{questionId:Number(id),count:1}:action==='adaptive'?{subject:target.dataset.subject,lesson:target.dataset.lesson,type:target.dataset.type,adaptive:true,count:5}:{review:true,count:10};const result=await api('practice',data);await start(result.studentAssignmentId);}
  if(action==='open-attempt'){state.attempt=await api('attempts/'+id);state.index=0;await navigate('attempt');}
  if(action==='teacher-attempt')await teacherAttempt(id);
  if(action==='back-assignments'){await saveDraft();await navigate('assignments');}
  if(action==='save-answer'){await saveDraft();toast('Đã lưu nháp.');}
  if(['previous','next','goto-question'].includes(action)){clearTimeout(autosave);await saveDraft();state.index=action==='goto-question'?Number(id):state.index+(action==='next'?1:-1);await renderAttempt();}
  if(action==='hint'){clearTimeout(autosave);await saveDraft();state.attempt=await api(`attempts/${state.attempt.id}/hint`,{questionId:state.attempt.questions[state.index].id});await renderAttempt();}
  if(action==='explain'){toast('Đang tạo giải thích theo lời giải đã duyệt…');await api(`attempts/${state.attempt.id}/explain`,{questionId:state.attempt.questions[state.index].id});await renderAttempt();}
  if(action==='finish'){await saveDraft();showModal('Kết thúc bài làm?',`<p>Các đáp án nháp đã được lưu sẽ được nộp. Em sẽ không thể sửa sau khi kết thúc.</p><form id="finish-form">${buttons('Kết thúc & nộp bài')}</form>`);}
  if(action==='ai-suggest'){toast('Đang phân tích kết quả học tập…');const result=await api('recommendations',{});await showRecommendations();toast(result.message||'Đã cập nhật đề xuất AI.');}
 } catch(error){toast(error.message);}finally{target.disabled=false;}
});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const data=Object.fromEntries(new FormData(form)),submit=form.querySelector('[type=submit]')||form.querySelector('button.primary');if(submit?.disabled)return;if(submit)submit.disabled=true;
 try {
  if(form.id==='login-form'){const result=await api('login',data);state.user=result.user;state.csrf=result.csrf;state.ai=result.aiConfigured;await navigate(state.user.must_change?'account':'overview');return;}
  if(form.id==='student-form'){await api('students'+(form.dataset.id?'/'+form.dataset.id:''),{...data,...(form.dataset.id?{action:'edit'}:{})});modal.close();toast('Đã lưu tài khoản học sinh.');await students();}
  if(form.id==='lock-form'){await api('students/'+form.dataset.id,{action:'lock'});modal.close();await students();}
  if(form.id==='reset-form'){await api('students/'+form.dataset.id,{action:'reset',password:data.password});modal.close();toast('Đã cấp lại mật khẩu. Hãy cung cấp mật khẩu tạm trực tiếp cho học sinh.');await students();}
  if(form.id==='upload-form'){const file=form.elements.file.files[0];let payload={title:data.title,content:data.content};if(file){if(file.size>30*1024*1024)throw new Error('Tệp tối đa 30 MB.');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});payload={title:data.title,filename:file.name,base64};}toast('Đang lưu và trích xuất tài liệu…');await api('documents',payload);modal.close();await documents();toast('Đã lưu. Kiểm tra và xác nhận phân tích để tạo bài tập.');}
  if(form.id==='document-confirm'){await api('documents/'+form.dataset.id+'/confirm',{theory:data.theory,types:data.types.split('\n').filter(Boolean),steps:data.steps.split('\n').filter(Boolean)});modal.close();await documents();toast('Đã xác nhận tài liệu.');}
  if(form.id==='question-form'){const payload={...data,options:data.options.split('\n').filter(Boolean),hints:data.hints.split('\n').filter(Boolean),sources:[{documentId:Number(data.documentId),location:data.location,quote:data.quote}],...(form.dataset.id?{action:'edit'}:{})};await api('questions'+(form.dataset.id?'/'+form.dataset.id:''),payload);modal.close();await questions();toast('Đã lưu bản nháp. Hãy kiểm tra và phê duyệt.');}
  if(form.id==='approve-form'){await api('questions/'+form.dataset.id,{action:'approve',acknowledgeDuplicates:true});modal.close();await questions();toast('Đã phê duyệt. Bạn có thể xuất bản bài tập.');}
  if(form.id==='generate-form'){toast('AI đang tạo bản nháp. Vui lòng giữ cửa sổ này mở…');const result=await api('generate',{...data,documentIds:new FormData(form).getAll('documentIds').map(Number)});if(result.conflicts?.length)throw new Error('Nguồn có mâu thuẫn: '+result.conflicts.join('; '));modal.close();await questions();toast(`Đã tạo ${result.created}/${result.requested} bản nháp. Kiểm tra nội dung trước khi duyệt.`);}
  if(form.id==='assignment-form'){await api('assignments',{...data,studentIds:new FormData(form).getAll('studentIds').map(Number),variants:form.elements.variants.checked,allow_hints:form.elements.allow_hints.checked,opens_at:data.opens_at?new Date(data.opens_at).toISOString():null,closes_at:data.closes_at?new Date(data.closes_at).toISOString():null});modal.close();await assignments();toast('Đã tạo đề và giao cho học sinh.');}
  if(form.id==='password-form'){if(data.password!==data.confirm)throw new Error('Hai mật khẩu mới chưa khớp.');await api('password',data);state.user.must_change=false;toast('Đổi mật khẩu thành công.');await navigate('overview');}
  if(form.id==='answer-form'){clearTimeout(autosave);state.attempt=await api(`attempts/${state.attempt.id}/answer`,{questionId:Number(form.dataset.question),response:data.response});await renderAttempt();}
  if(form.id==='finish-form'){clearTimeout(autosave);state.attempt=await api(`attempts/${state.attempt.id}/finish`,{});modal.close();await renderAttempt();toast('Bài làm đã được nộp.');}
  if(form.classList.contains('grade-form')){await api('grade',{attemptId:Number(form.dataset.attempt),questionId:Number(form.dataset.question),correct:data.correct==='1',feedback:data.feedback});toast('Đã lưu đánh giá.');await teacherAttempt(form.dataset.attempt);}
 }catch(error){if(form.id==='login-form')$('#login-error').innerHTML=`<p class="error spacer">${e(error.message)}</p>`;else toast(error.message);}finally{if(submit)submit.disabled=false;}
});
try{const result=await api('me');state.user=result.user;state.csrf=result.csrf;state.ai=result.aiConfigured;await navigate('overview');}catch{renderLogin();}
